def is_leap_year(year: int) -> bool:
    """Check if year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def days_in_month(year: int, month: int) -> int:
    """Get number of days in a given month."""
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    elif month == 2:
        return 29 if is_leap_year(year) else 28
    else:
        raise ValueError(f"Invalid month: {month}")

def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Calculate the next fire time for a cron expression.

    Args:
        expr: 5-field cron expression (minute hour day-of-month month day-of-week)
        after: datetime after which to find the next match

    Returns:
        The next matching datetime with seconds and microseconds set to 0

    Raises:
        ValueError: If the expression is invalid or no match is found within 5 years
    """
    # Parse expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Invalid cron expression: expected 5 fields, got {len(fields)}")

    minute_field, hour_field, day_field, month_field, weekday_field = fields

    # Parse each field
    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)

    # For day of month, we'll validate in the main loop since we need actual days in month
    # For now, parse to a set, but we'll validate actual day ranges later
    day_of_month_set = parse_field(day_field, 1, 31)

    months = parse_field(month_field, 1, 12, MONTH_NAMES)
    weekdays = parse_field(weekday_field, 0, 7, WEEKDAY_NAMES)

    # Normalize weekday 7 to 0 (Sunday)
    if 7 in weekdays:
        weekdays.add(0)
    weekdays.discard(7)

    # Check if fields are restricted (not exactly '*')
    day_of_month_restricted = day_field.strip() != '*'
    day_of_week_restricted = weekday_field.strip() != '*'

    # Start searching from after + 1 minute (to ensure strictly after)
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # We'll search up to 5 years ahead
    max_year = current.year + 5

    # Search loop
    while True:
        # Check if we've exceeded 5 years
        if current.year > max_year:
            raise ValueError("No matching time found within 5 years")

        # Extract components
        current_minute = current.minute
        current_hour = current.hour
        current_day = current.day
        current_month = current.month
        current_year = current.year
        current_weekday = current.weekday()  # Monday is 0, Sunday is 6

        # Convert to cron weekday (Sunday = 0)
        cron_weekday = (current_weekday + 1) % 7

        # Check month
        if current_month not in months:
            # Move to next month
            if current_month == 12:
                current = datetime.datetime(current_year + 1, 1, 1, 0, 0)
            else:
                current = datetime.datetime(current_year, current_month + 1, 1, 0, 0)
            continue

        # Check day matching (Vixie cron rule)
        # If both day-of-month and day-of-week are restricted, either must match
        # Otherwise, both must match

        day_matches = False
        if day_of_month_restricted and day_of_week_restricted:
            # Either must match
            if current_day in day_of_month_set or cron_weekday in weekdays:
                day_matches = True
        else:
            # Both must match
            if current_day in day_of_month_set and cron_weekday in weekdays:
                day_matches = True

        # If day doesn't match, move to next day
        if not day_matches:
            # Move to next day
            days_in_current_month = days_in_month(current_year, current_month)
            if current_day == days_in_current_month:
                if current_month == 12:
                    current = datetime.datetime(current_year + 1, 1, 1, 0, 0)
                else:
                    current = datetime.datetime(current_year, current_month + 1, 1, 0, 0)
            else:
                current = datetime.datetime(current_year, current_month, current_day + 1, 0, 0)
            continue

        # Check hour
        if current_hour not in hours:
            # Move to next hour
            current = current.replace(minute=0, second=0, microsecond=0) + datetime.timedelta(hours=1)
            continue

        # Check minute
        if current_minute not in minutes:
            # Move to next minute
            current = current.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
            continue

        # All conditions matched
        return current.replace(second=0, microsecond=0)
