import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        i = 0
        # Find the first interval that might overlap or touch
        while i < len(self._iv) and self._iv[i][1] < start:
            i += 1
        j = i
        # Merge all overlapping or touching intervals
        while j < len(self._iv) and self._iv[j][0] <= end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                # No overlap - keep the whole interval
                out.append((s, e))
            else:
                # There is overlap
                if s < start:
                    # Keep the part before removal
                    out.append((s, start))
                if e > end:
                    # Keep the part after removal
                    out.append((end, e))
        self._iv = out

    def contains(self, x):
        for s, e in self._iv:
            if s <= x < e:
                return True
        return False

    def free(self, lo, hi):
        gaps = []
        cur = lo
        for s, e in self._iv:
            if s > cur:
                # There's a gap from cur to s
                gaps.append((cur, min(s, hi)))
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
