import heapq
from collections import defaultdict
from typing import Optional, Tuple


def route(grid: list[str]) -> Optional[Tuple[int, str]]:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0])

    # Check for ragged rows and valid characters
    for row in grid:
        if len(row) != cols:
            raise ValueError("Ragged rows")

    # Find start, end, and teleport pads
    start = None
    end = None
    pads = defaultdict(list)  # letter -> list of positions
    valid_chars = set('S#E.123456789')

    # Add lowercase letters to valid characters
    for i in range(ord('a'), ord('z') + 1):
        valid_chars.add(chr(i))

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("Multiple starts")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Multiple ends")
                end = (r, c)
            elif ch.islower():
                pads[ch].append((r, c))
                # Check if a letter appears more than twice
                if len(pads[ch]) > 2:
                    raise ValueError(f"Letter '{ch}' appears more than twice")
            elif ch == '#' or ch == '.' or ch.isdigit():
                pass  # Valid
            else:
                raise ValueError(f"Unknown character '{ch}'")

    if start is None:
        raise ValueError("No start position")
    if end is None:
        raise ValueError("No end position")

    # Check all letters appear exactly 0 or 2 times
    for letter, positions in pads.items():
        if len(positions) != 2:
            raise ValueError(f"Letter '{letter}' appears {len(positions)} times (must be 0 or 2)")

    # Helper function to get cost of a cell
    def get_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E' or ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1  # Pad costs 1
        return None  # Shouldn't happen

    # Directions: order by lexicographic order in the required alphabet: D < L < R < T < U
    # But we need to consider the actual moves: U, D, L, R for neighbors, and T for teleport
    # The lexicographic order is: D < L < R < T < U
    directions = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('T', None, None),  # teleport - special handling
        ('U', -1, 0),
    ]

    # Precompute pad positions for teleportation
    pad_map = {}
    for letter, positions in pads.items():
        pos1, pos2 = positions
        pad_map[pos1] = pos2
        pad_map[pos2] = pos1

    # Dijkstra's algorithm with priority queue
    # Priority: (cost, moves_string) - but we need to compare lexicographically
    # Instead, we store state as (cost, moves_string, r, c)

    # For efficiency, use (cost, moves) as key but track lexicographic ordering properly
    # Use a tuple (cost, moves) as priority in heap
    # Since heapq is min-heap, we want smallest cost first, then lexicographically smallest moves

    # dist[r][c] = (min_cost, best_moves_to_reach)
    dist = {}

    # Start position
    sr, sc = start
    # Initial cost is 1 for S
    start_cost = 1
    start_moves = ""

    # Priority queue: (cost, moves, r, c)
    pq = [(start_cost, start_moves, sr, sc)]
    dist[(sr, sc)] = (start_cost, start_moves)

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        # Skip if we found a better path already
        if (r, c) in dist and dist[(r, c)] < (cost, moves):
            continue

        # Check if reached end
        if (r, c) == end:
            return (cost, moves)

        # Explore neighbors
        for move, dr, dc in directions:
            if move == 'T':
                # Teleportation
                ch = grid[r][c]
                if ch.islower():
                    # Find the other pad
                    if (r, c) in pad_map:
                        tr, tc = pad_map[(r, c)]
                        teleport_cost = 2
                        new_cost = cost + teleport_cost
                        new_moves = moves + move

                        # Check if this path is better
                        if (tr, tc) not in dist or dist[(tr, tc)] > (new_cost, new_moves):
                            dist[(tr, tc)] = (new_cost, new_moves)
                            heapq.heappush(pq, (new_cost, new_moves, tr, tc))
            else:
                # Regular move
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    cell = grid[nr][nc]
                    if cell != '#':  # Not a wall
                        move_cost = get_cost(nr, nc)
                        new_cost = cost + move_cost
                        new_moves = moves + move

                        # Check if this path is better
                        if (nr, nc) not in dist or dist[(nr, nc)] > (new_cost, new_moves):
                            dist[(nr, nc)] = (new_cost, new_moves)
                            heapq.heappush(pq, (new_cost, new_moves, nr, nc))

    # End unreachable
    return None
