import re
from typing import Optional, List, Tuple, Set

# Token types for the range parser
class TokenType:
    TILDE = '~'
    CARET = '^'
    GT = '>'
    LT = '<'
    EQ = '='
    DOT = '.'
    STAR = '*'
    HYPHEN = '-'
    OR = '||'
    SPACE = ' '
    PRERELEASE = '-'
    BUILD = '+'
    VERSION = 'version'
    X_RANGE = 'x'
    EOF = 'eof'

class Token:
    def __init__(self, type_: str, value=None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(range_str: str) -> List[Token]:
    """Tokenize a version range string."""
    tokens = []
    i = 0
    while i < len(range_str):
        # Skip whitespace
        if range_str[i].isspace():
            i += 1
            continue

        # Check for || (must check before single |)
        if range_str[i:i+2] == '||':
            tokens.append(Token(TokenType.OR))
            i += 2
            continue

        # Check for operators
        if range_str[i:i+2] in ['>=', '<=', '==', '!=']:
            tokens.append(Token(TokenType.EQ, range_str[i:i+2]))
            i += 2
            continue

        if range_str[i] in ['<', '>', '=']:
            tokens.append(Token(TokenType.EQ, range_str[i]))
            i += 1
            continue

        # Check for tilde
        if range_str[i] == '~':
            tokens.append(Token(TokenType.TILDE))
            i += 1
            continue

        # Check for caret
        if range_str[i] == '^':
            tokens.append(Token(TokenType.CARET))
            i += 1
            continue

        # Check for hyphen
        if range_str[i] == '-':
            tokens.append(Token(TokenType.HYPHEN))
            i += 1
            continue

        # Check for *
        if range_str[i] == '*':
            tokens.append(Token(TokenType.STAR))
            i += 1
            continue

        # Check for .
        if range_str[i] == '.':
            tokens.append(Token(TokenType.DOT))
            i += 1
            continue

        # Check for x (case insensitive)
        if range_str[i].lower() == 'x':
            tokens.append(Token(TokenType.X_RANGE))
            i += 1
            continue

        # Check for prerelease/build markers
        if range_str[i] == '-' or range_str[i] == '+':
            tokens.append(Token(TokenType.PRERELEASE if range_str[i] == '-' else TokenType.BUILD))
            i += 1
            continue

        # Check for numeric part
        if range_str[i].isdigit():
            j = i
            while j < len(range_str) and range_str[j].isdigit():
                j += 1
            value = range_str[i:j]
            # Check for leading zeros
            if len(value) > 1 and value[0] == '0':
                raise ValueError(f"Invalid version: leading zeros not allowed in numeric part")
            tokens.append(Token(TokenType.VERSION, int(value)))
            i = j
            continue

        # Check for alphanumeric part (prerelease/build identifier)
        if range_str[i].isalnum() or range_str[i] == '-':
            j = i
            while j < len(range_str) and (range_str[j].isalnum() or range_str[j] == '-'):
                j += 1
            value = range_str[i:j]
            tokens.append(Token(TokenType.VERSION, value))
            i = j
            continue

        raise ValueError(f"Invalid character in range: {range_str[i]}")

    return tokens + [Token(TokenType.EOF)]

class RangeParser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset=0) -> Token:
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return Token(TokenType.EOF)

    def advance(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def match(self, *types) -> bool:
        for t in types:
            if self.peek().type == t:
                self.advance()
                return True
        return False

    def parse(self):
        """Parse the full range."""
        return self.parse_range()

    def parse_range(self):
        """Parse a range (one or more comparator sets joined by ||)."""
        sets = []
        while True:
            comp_set = self.parse_comparator_set()
            sets.append(comp_set)

            if self.match(TokenType.OR):
                continue
            else:
                break

        # Check for EOF
        if self.peek().type != TokenType.EOF:
            raise ValueError("Unexpected token in range")

        return sets

    def parse_comparator_set(self):
        """Parse a set of comparators that must all match (whitespace-separated)."""
        comparators = []

        while self.peek().type not in [TokenType.EOF, TokenType.OR] and not self.match(TokenType.OR):
            comp = self.parse_comparator()
            comparators.append(comp)

            # Check for whitespace separation (skip spaces)
            while self.peek().type == TokenType.SPACE:
                self.advance()

        return comparators

    def parse_comparator(self):
        """Parse a single comparator: [~^><=][version]."""
        op = None
        if self.match(TokenType.TILDE):
            op = "~"
        elif self.match(TokenType.CARET):
            op = "^"
        elif self.match(TokenType.GT):
            op = ">"
        elif self.match(TokenType.LT):
            op = "<"
        elif self.match(TokenType.EQ):
            op = "="

        # Parse version (may be partial)
        version = self.parse_version()

        # If no operator was specified, treat as exact version
        if op is None:
            op = "="

        return Comparator(op, version)

    def parse_version(self):
        """Parse a (possibly partial) version."""
        major = None
        minor = None
        patch = None
        prerelease = []
        build = []

        # Parse major part
        if self.match(TokenType.VERSION):
            major = self.tokens[self.pos-1].value
        elif self.match(TokenType.X_RANGE):
            major = "x"
        elif self.match(TokenType.STAR):
            major = "*"
        else:
            raise ValueError("Expected version number or x-range")

        # Check for .minor
        if self.match(TokenType.DOT):
            if self.match(TokenType.VERSION):
                minor = self.tokens[self.pos-1].value
            elif self.match(TokenType.X_RANGE):
                minor = "x"
            elif self.match(TokenType.STAR):
                minor = "*"
            else:
                raise ValueError("Expected minor version number or x")

            # Check for .patch
            if self.match(TokenType.DOT):
                if self.match(TokenType.VERSION):
                    patch = self.tokens[self.pos-1].value
                elif self.match(TokenType.X_RANGE):
                    patch = "x"
                elif self.match(TokenType.STAR):
                    patch = "*"
                else:
                    raise ValueError("Expected patch version number or x")

            # Parse prerelease and build metadata
            prerelease, build = self.parse_prerelease_and_build()

        return VersionComponent(major, minor, patch, prerelease, build)

    def parse_prerelease_and_build(self):
        """Parse optional prerelease and build metadata."""
        prerelease = []
        build = []

        # Prerelease
        while self.match(TokenType.PRERELEASE):
            if self.match(TokenType.VERSION):
                prerelease.append(self.tokens[self.pos-1].value)
            else:
                raise ValueError("Expected prerelease identifier")

        # Build
        while self.match(TokenType.BUILD):
            if self.match(TokenType.VERSION):
                build.append(self.tokens[self.pos-1].value)
            else:
                raise ValueError("Expected build metadata identifier")

        return prerelease, build

class VersionComponent:
    def __init__(self, major, minor, patch, prerelease, build):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def to_version(self) -> 'Version':
        """Convert to a full version. X-ranges become 0."""
        def to_int_or_none(val):
            if val is None:
                return None
            if val == "x" or val == "*":
                return 0
            return int(val)

        return Version(
            to_int_or_none(self.major),
            to_int_or_none(self.minor),
            to_int_or_none(self.patch),
            self.prerelease.copy() if self.prerelease else None,
            self.build.copy() if self.build else None
        )

class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease=None, build=None):
        if major < 0 or minor < 0 or patch < 0:
            raise ValueError("Version numbers must be non-negative")

        # Check for leading zeros in numeric parts
        if major > 0 and str(major).startswith('0'):
            raise ValueError("Leading zeros not allowed in numeric part")
        if minor > 0 and str(minor).startswith('0'):
            raise ValueError("Leading zeros not allowed in numeric part")
        if patch > 0 and str(patch).startswith('0'):
            raise ValueError("Leading zeros not allowed in numeric part")

        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # None if release version, list of identifiers otherwise
        self.build = build  # Build metadata, ignored in comparisons

        # Validate prerelease identifiers if present
        if self.prerelease is not None:
            for identifier in self.prerelease:
                if isinstance(identifier, int):
                    if identifier < 0 or (identifier > 0 and str(identifier).startswith('0')):
                        raise ValueError("Invalid prerelease identifier")
                elif isinstance(identifier, str):
                    if not re.match(r'^[0-9A-Za-z-]+$', identifier) or identifier == "":
                        raise ValueError("Invalid prerelease identifier")
                else:
                    raise ValueError("Prerelease identifier must be int or string")

        # Validate build metadata if present
        if self.build is not None:
            for identifier in self.build:
                if isinstance(identifier, str):
                    if not re.match(r'^[0-9A-Za-z-]+$', identifier) or identifier == "":
                        raise ValueError("Invalid build metadata identifier")
                else:
                    raise ValueError("Build metadata identifier must be string")

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += "-" + ".".join(map(str, self.prerelease))
        if self.build is not None:
            s += "+" + ".".join(map(str, self.build))
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False

        return (
            self.major == other.major and
            self.minor == other.minor and
            self.patch == other.patch and
            self.prerelease == other.prerelease
        )

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented

        # Compare major, minor, patch
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # If we get here, the numeric parts are equal
        # If both are releases (prerelease is None), they're equal
        if self.prerelease is None and other.prerelease is None:
            return False  # They're equal, so not less
        # Release > prerelease
        if self.prerelease is None and other.prerelease is not None:
            return False
        if self.prerelease is not None and other.prerelease is None:
            return True

        # Both have prerelease, compare identifier lists
        # A shorter list is less than a longer one if it's a prefix
        for i in range(min(len(self.prerelease), len(other.prerelease))):
            self_id = self.prerelease[i]
            other_id = other.prerelease[i]

            # Convert to comparable types
            self_is_num = isinstance(self_id, int)
            other_is_num = isinstance(other_id, int)

            if self_is_num and other_is_num:
                # Numeric comparison
                if self_id != other_id:
                    return self_id < other_id
            elif self_is_num and not other_is_num:
                # Numeric < alphanumeric
                return True
            elif not self_is_num and other_is_num:
                # Alphanumeric > numeric
                return False
            else:
                # Both alphanumeric: ASCII comparison
                if str(self_id) != str(other_id):
                    return str(self_id) < str(other_id)

        # If we've compared all identifiers and they're equal up to min length,
        # shorter list is less than longer list
        return len(self.prerelease) < len(other.prerelease)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return not (self < other)

    def __hash__(self):
        # Build metadata ignored for hashing
        return hash((self.major, self.minor, self.patch, 
                     tuple(self.prerelease) if self.prerelease is not None else None))

def parse(v: str) -> Version:
    """Parse a semantic version string."""
    if not v:
        raise ValueError("Empty version string")

    # Remove leading 'v' or '='
    if v[0].lower() == 'v' or v[0] == '=':
        v = v[1:].lstrip()

    # Validate format with regex
    # Pattern from SemVer 2.0.0
    semver_pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(semver_pattern, v)
    if not match:
        raise ValueError(f"Invalid version: {v}")

    major, minor, patch, prerelease, build = match.groups()

    # Parse prerelease if present
    prerelease_list = None
    if prerelease:
        prerelease_list = []
        for identifier in prerelease.split('.'):
            # Check for leading zeros in numeric parts
            if identifier.isdigit():
                if len(identifier) > 1 and identifier[0] == '0':
                    raise ValueError("Leading zeros not allowed in prerelease numeric part")
                prerelease_list.append(int(identifier))
            else:
                prerelease_list.append(identifier)

    # Parse build metadata if present
    build_list = None
    if build:
        build_list = []
        for identifier in build.split('.'):
            build_list.append(identifier)

    return Version(int(major), int(minor), int(patch), prerelease_list, build_list)

class Comparator:
    def __init__(self, op: str, version: VersionComponent):
        self.op = op
        self.version = version

    def __repr__(self):
        return f"{self.op}{self.version}"

    def satisfies(self, version: Version) -> bool:
        """Check if this comparator is satisfied by the given version."""
        # Handle x-range cases: convert version to full version for comparison
        # If version is partial (x-ranges), convert to full version for comparison
        comp_version = self.version.to_version()

        # If version has build metadata, strip it for comparison
        # but prerelease info matters for comparison
        v = Version(version.major, version.minor, version.patch, 
                   version.prerelease, None)
        cv = Version(comp_version.major, comp_version.minor, comp_version.patch,
                    comp_version.prerelease, None)

        if self.op == '=' or self.op == '==':
            return v == cv
        elif self.op == '>':
            return v > cv
        elif self.op == '<':
            return v < cv
        elif self.op == '>=':
            return v >= cv
        elif self.op == '<=':
            return v <= cv
        elif self.op == '~':
            # Tilde: >=v <next minor (or major if minor and patch not specified)
            if self.version.minor == "x" or self.version.minor == "*" or self.version.minor is None:
                # ~1 means >=1.0.0 <2.0.0
                return v.major == cv.major and v >= cv
            elif self.version.patch == "x" or self.version.patch == "*" or self.version.patch is None:
                # ~1.2 means >=1.2.0 <1.3.0
                return v.major == cv.major and v.minor == cv.minor and v >= cv
            else:
                # ~1.2.3 means >=1.2.3 <1.3.0
                return v.major == cv.major and v.minor == cv.minor and v.patch == cv.patch and v >= cv
        elif self.op == '^':
            # Caret: >=v <next major (unless major is 0)
            # Special handling for major 0
            if cv.major == 0:
                if cv.minor == 0:
                    # ^0.0.3 means >=0.0.3 <0.0.4
                    return v.major == cv.major and v.minor == cv.minor and v.patch == cv.patch and v >= cv
                else:
                    # ^0.2.3 means >=0.2.3 <0.3.0
                    return v.major == cv.major and v.minor == cv.minor and v >= cv
            else:
                # ^1.2.3 means >=1.2.3 <2.0.0
                if v.major != cv.major:
                    return False
                return v >= cv
        else:
            raise ValueError(f"Unknown operator: {self.op}")

def satisfies(version: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        v = parse(version)
    except ValueError:
        return False

    try:
        sets = RangeParser(tokenize(rng)).parse()
    except ValueError:
        return False

    # Check if any set satisfies the version
    for comp_set in sets:
        all_match = True
        for comp in comp_set:
            if not comp.satisfies(v):
                all_match = False
                break

        if all_match:
            return True

    return False

def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version that satisfies the range, or None."""
    if not versions:
        return None

    # Parse the range
    try:
        sets = RangeParser(tokenize(rng)).parse()
    except ValueError:
        return None

    # Check each version
    satisfying_versions = []
    for ver_str in versions:
        try:
            v = parse(ver_str)
        except ValueError:
            # Skip invalid versions
            continue

        # Check if version satisfies any set
        if any(is_version_in_set(v, comp_set) for comp_set in sets):
            satisfying_versions.append((v, ver_str))

    if not satisfying_versions:
        return None

    # Sort by version (highest first)
    satisfying_versions.sort(key=lambda x: x[0], reverse=True)

    return satisfying_versions[0][1]

def is_version_in_set(version: Version, comp_set: List[Comparator]) -> bool:
    """Check if version satisfies all comparators in a set."""
    for comp in comp_set:
        if not comp.satisfies(version):
            return False
    return True

# Re-implement parse for range components with the full version
def parse_range_version(v: str) -> VersionComponent:
    """Parse a version that might be partial (for range components)."""
    if not v:
        raise ValueError("Empty version string")

    # Remove leading 'v' or '='
    if v[0].lower() == 'v' or v[0] == '=':
        v = v[1:].lstrip()

    # Split by . to get parts
    parts = v.split('.')
    if len(parts) > 3:
        raise ValueError("Too many version components")

    major = None
    minor = None
    patch = None
    prerelease = []
    build = []

    # Parse major
    if parts[0].lower() == 'x' or parts[0] == '*':
        major = parts[0].lower()
    elif parts[0].isdigit():
        major = int(parts[0])
    else:
        raise ValueError(f"Invalid major version: {parts[0]}")

    # Parse minor if present
    if len(parts) > 1:
        if parts[1].lower() == 'x' or parts[1] == '*':
            minor = parts[1].lower()
        elif parts[1].isdigit():
            minor = int(parts[1])
        else:
            raise ValueError(f"Invalid minor version: {parts[1]}")

        # Parse patch if present
        if len(parts) > 2:
            patch_part = parts[2]
            # Check for prerelease/build markers
            if '-' in patch_part:
                patch_part, pre_part = patch_part.split('-', 1)
                prerelease = pre_part.split('.')
            if '+' in patch_part:
                patch_part, build_part = patch_part.split('+', 1)
                build = build_part.split('.')

            if patch_part.lower() == 'x' or patch_part == '*':
                patch = patch_part.lower()
            elif patch_part.isdigit():
                patch = int(patch_part)
            else:
                raise ValueError(f"Invalid patch version: {patch_part}")

    # If prerelease or build are present, convert to list of identifiers
    prerelease_list = []
    for identifier in prerelease:
        # Check if identifier is numeric
        if identifier.isdigit():
            prerelease_list.append(int(identifier))
        else:
            prerelease_list.append(identifier)

    build_list = build  # Keep as strings

    # Create a partial version
    return VersionComponent(major, minor, patch, prerelease_list, build_list)
