def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Parse a command line string into words, supporting shell-like quoting and parameter expansion.

    Args:
        line: The input command line string.
        env: Environment variables dictionary for expansion.

    Returns:
        List of parsed words.

    Raises:
        ValueError: For unterminated quotes, unterminated ${, or trailing unescaped backslash.
    """
    if not line:
        return []

    result = []
    i = 0
    n = len(line)

    # Tokenize the line into parts (quoted and unquoted segments)
    tokens = []

    while i < n:
        if line[i] in ' \t\n':
            # Skip whitespace in unquoted context
            i += 1
            continue

        if line[i] == "'":
            # Single-quoted string: everything is literal up to the next '
            start = i + 1
            i += 1
            while i < n and line[i] != "'":
                i += 1
            if i >= n:
                raise ValueError("Unterminated single quote")
            tokens.append(('SINGLE_QUOTE', line[start:i]))
            i += 1  # skip the closing '
            continue

        if line[i] == '"':
            # Double-quoted string: literal except backslash escapes $, ", \, newline
            # and $ expansion happens inside
            tokens.append(('DOUBLE_QUOTE', _parse_double_quote(line, i, env)))
            # Find the end of the double-quoted string
            i += 1
            while i < n and line[i] != '"':
                if line[i] == '\\' and i + 1 < n and line[i+1] in '$"\\\n':
                    i += 2  # Skip the backslash and the escaped character
                else:
                    i += 1
            if i >= n:
                raise ValueError("Unterminated double quote")
            i += 1  # Skip the closing "
            continue

        if line[i] == '$':
            # Parameter expansion
            if i + 1 < n and line[i+1] == '{':
                # ${...}
                start = i + 2
                depth = 1
                j = start
                while j < n and depth > 0:
                    if line[j] == '{':
                        depth += 1
                    elif line[j] == '}':
                        depth -= 1
                    j += 1
                if depth > 0:
                    raise ValueError("Unterminated ${")
                content = line[i+2:j-1]
                if j < len(line) and line[j] == '"':  # If next char is quote, it will be handled in next iteration
                    pass
                # Parse parameter expansion
                expansion_result, _ = _parse_parameter_expansion(content, env, line, j)
                tokens.append(('EXPANSION', expansion_result))
                i = j
                continue
            else:
                # $NAME or $x style expansion
                j = i + 1
                if j < n and line[j].isalpha() or line[j] == '_':
                    while j < n and (line[j].isalnum() or line[j] == '_'):
                        j += 1
                    name = line[i+1:j]
                    value = env.get(name, '')
                    tokens.append(('EXPANSION', value))
                    i = j
                    continue
                elif j < n and line[j].isdigit():
                    # $0, $1 etc - not standard POSIX but common
                    while j < n and line[j].isdigit():
                        j += 1
                    name = line[i+1:j]
                    value = env.get(name, '')
                    tokens.append(('EXPANSION', value))
                    i = j
                    continue
                else:
                    # Just a literal $
                    tokens.append(('LITERAL_DOLLAR', '$'))
                    i += 1
                    continue

        if line[i] == '\\':
            # Unquoted backslash - escapes the next character
            if i + 1 >= n:
                raise ValueError("Trailing unescaped backslash")
            next_char = line[i+1]
            if next_char == '\n':
                # Backslash-newline is removed entirely
                i += 2
                continue
            elif i + 1 < n:
                # Backslash escapes the next character
                # Check if this backslash is in a quoted context by looking at tokens
                # For now, assume unquoted context since we skip whitespace and quotes above
                tokens.append(('BACKSLASH_ESCAPE', next_char))
                i += 2
                continue
            else:
                raise ValueError("Trailing unescaped backslash")

        # Regular unquoted character
        start = i
        while i < n and line[i] not in ' \t\n\'"$' and not (line[i] == '\\' and i+1 < n):
            i += 1
        tokens.append(('UNQUOTED', line[start:i]))

    # Now process tokens into words
    words = []
    current_word = []

