            # Actually, expansions in double quotes don't trigger field splitting
            # Unquoted expansions trigger field splitting
            current_word.append(token_value)
        elif token_type == 'LITERAL_DOLLAR':
            current_word.append(token_value)
        elif token_type == 'BACKSLASH_ESCAPE':
