    # We need to handle the case where adjacent quoted/unquoted parts join into one word
    # This is tricky because our tokenization split by quote boundaries.

    # Alternative approach: build words during parsing while handling context properly
    # Let's implement a state machine with proper context tracking

    # Reset and use a different approach for clarity
    result = []
    i = 0
    n = len(line)

    while i < n:
        # Skip whitespace in unquoted context
