                if line[i+1] == '\n':
                    raise ValueError("Trailing unescaped backslash")
                word_chars.append(line[i+1])
                i += 2
            else:
                word_chars.append(line[i])
                i += 1
        result.append(''.join(word_chars))

    return result


def _parse_parameter_expansion(content: str, env: dict[str, str], line: str, after_brace: int) -> tuple[str, int]:
    """
    Parse a parameter expansion of the form ${NAME:-default}, ${NAME-default}, or ${NAME}.

    Returns (value, next_index).
    """
    if not content:
        raise ValueError("Empty ${} expansion")

    # Find variable name and potential default
    j = 0
    while j < len(content) and (content[j].isalnum() or content[j] == '_'):
        j += 1

    if j == 0:
        raise ValueError(f"Invalid parameter expansion: ${{{content}}}")

    name = content[:j]
    rest = content[j:]

    if not rest:
        # Simple expansion: ${NAME}
        return env.get(name, ''), after_brace

    if rest[0] == ':':
        if rest.startswith(':-'):
            # ${NAME:-default}
            default_text = rest[2:]
            value = env.get(name, '')
            if value == '':
                # Expand default text
                default_value = _expand_simple_dollar(default_text, env, line, after_brace + len(rest))
                return default_value, after_brace + len(rest)
            else:
                return value, after_brace + len(rest)
        else:
            raise ValueError(f"Invalid parameter expansion syntax: ${{{content}}}")

    elif rest[0] == '-':
        # ${NAME-default}
        default_text = rest[1:]
        value = env.get(name, '')
        if value == '':
            # Expand default text
            default_value = _expand_simple_dollar(default_text, env, line, after_brace + len(rest))
            return default_value, after_brace + len(rest)
        else:
            return value, after_brace + len(rest)

    else:
        raise ValueError(f"Invalid parameter expansion syntax: ${{{content}}}")


def _expand_simple_dollar(text: str, env: dict[str, str], line: str, pos: int) -> str:
    """
    Expand $VAR in simple text (not in braces).
    This is used for defaults in parameter expansion.
    """
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '$':
            if i + 1 < n and text[i+1] == '{':
                # We won't handle ${} in default text for simplicity per problem statement
                raise ValueError("Nested ${} not supported in default text")
            elif i + 1 < n and (text[i+1].isalpha() or text[i+1] == '_'):
                j = i + 1
                while j < n and (text[j].isalnum() or text[j] == '_'):
                    j += 1
                name = text[i+1:j]
                result.append(env.get(name, ''))
                i = j
            else:
                result.append('$')
                i += 1
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)


def _parse_double_quote(line: str, start: int, env: dict[str, str]) -> str:
    """
    Parse a double-quoted string segment and handle escapes and $ expansion.
    Returns the parsed string.
    """
    result = []
    i = start + 1  # Skip the opening "
    n = len(line)

    while i < n and line[i] != '"':
        if line[i] == '\\' and i + 1 < n:
            next_char = line[i+1]
            if next_char in '$"\\\n':
                if next_char == '\n':
                    # Remove backslash-newline
                    i += 2
                    continue
                else:
                    result.append(next_char)
                    i += 2
                    continue
            else:
                # Backslash not escaping special char, so keep it and next char
                result.append('\\')
                result.append(next_char)
                i += 2
                continue
        elif line[i] == '$' and i + 1 < n and (line[i+1].isalpha() or line[i+1] == '_' or line[i+1] == '{'):
            # Expand variable
            if line[i+1] == '{':
                bracket_start = i + 2
                depth = 1
                j = bracket_start
                while j < n and depth > 0:
                    if line[j] == '{':
                        depth += 1
                    elif line[j] == '}':
                        depth -= 1
                    j += 1
                if depth > 0:
                    raise ValueError("Unterminated ${")
                content = line[i+2:j-1]
                expansion_result, next_i = _parse_parameter_expansion(content, env, line, j)
                result.append(expansion_result)
                i = j
                continue
            else:
                j = i + 1
                while j < n and (line[j].isalnum() or line[j] == '_'):
                    j += 1
                name = line[i+1:j]
                value = env.get(name, '')
                result.append(value)
                i = j
                continue
        else:
            result.append(line[i])
            i += 1

    if i >= n:
        raise ValueError("Unterminated double quote")

    # Don't include the closing "
    return ''.join(result)
