    origin = get_origin(cls)
    if origin is Literal:
        allowed_values = get_args(cls)
        for v in allowed_values:
            if type(v) is type(data) and v == data:
                return data
        raise LoadError(path, f"Value {data!r} is not one of the allowed literals {allowed_values}")

