            if data is None:
                return None
            return _load_value(non_none_arg, data, path)

        # Handle general union (try each option until one succeeds)
        errors = []
        for arg in args:
            try:
                return _load_value(arg, data, path)
            except LoadError as e:
                errors.append((arg, e))

        # If all fail, construct error message for the union itself
        if len(args) == 2 and any(get_origin(a) is Union for a in args):
            # Could be nested unions, use the last error as representative
            raise errors[-1][1]
        else:
            raise LoadError(path, f"Value {data!r} could not be loaded into any of the union types: {[str(a) for a in args]}")

