                result.append(_load_value(item_type, item, item_path))

            return tuple(result)

    # Handle dict
    if origin is dict:
        if not isinstance(data, dict):
            raise LoadError(path, f"Expected dict, got {type(data).__name__}")

        args = get_args(cls)
        if not args:
            return data

        key_type, value_type = args
        if key_type is not str:
            raise LoadError(path, "Only dict[str, T] is supported")

        result = {}
        for k, v in data.items():
            if not isinstance(k, str):
                raise LoadError(path, f"Dict keys must be strings, got {type(k).__name__}")
            result[k] = _load_value(value_type, v, f"{path}[{k}]")

        return result

    # Handle basic types
    if cls is int:
        if isinstance(data, bool) or not isinstance(data, int):
            raise LoadError(path, f"Expected int, got {type(data).__name__}")
        return data

    if cls is float:
        if isinstance(data, bool):
            raise LoadError(path, f"Expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise LoadError(path, f"Expected float, got {type(data).__name__}")

    if cls is str:
        if not isinstance(data, str):
            raise LoadError(path, f"Expected str, got {type(data).__name__}")
        return data

    if cls is bool:
        if not isinstance(data, bool):
            raise LoadError(path, f"Expected bool, got {type(data).__name__}")
        return data

    if cls is Any:
        return data

    # Fallback for unrecognized types
    raise LoadError(path, f"Unsupported type: {cls}")
